from solution import even_bit_toggle_number


def test_issue_example_10_to_0():
    """Example rule: even_bit_toggle_number(10) == 0."""
    assert even_bit_toggle_number(10) == 0  # 0b1010 ^ 0b1010 = 0b0000 = 0


def test_issue_zero_stays_zero():
    """Rule 'toggle all even bits': 0 has no set bits so stays 0."""
    assert even_bit_toggle_number(0) == 0  # 0 ^ 0 = 0


def test_issue_one_unchanged():
    """Rule 'toggle all even bits': single odd-position bit 1 stays 1."""
    assert even_bit_toggle_number(1) == 1  # 0b1 ^ 0b0 = 0b1 = 1


def test_issue_two_to_zero():
    """Rule 'toggle all even bits': 2 (0b10) becomes 0."""
    assert even_bit_toggle_number(2) == 0  # 0b10 ^ 0b10 = 0b00 = 0 (2 ^ 2 = 0)


def test_issue_three_to_one():
    """Rule 'toggle all even bits': 3 (0b11) becomes 1."""
    assert even_bit_toggle_number(3) == 1  # 0b11 ^ 0b10 = 0b01 = 1 (3 ^ 2 = 1)


def test_issue_four_to_six():
    """Rule 'toggle all even bits': 4 (0b100) becomes 6."""
    assert even_bit_toggle_number(4) == 6  # 0b100 ^ 0b010 = 0b110 = 6 (4 ^ 2 = 6)


def test_issue_seven_to_five():
    """Rule 'toggle all even bits': 7 (0b111) becomes 5."""
    assert even_bit_toggle_number(7) == 5  # 0b111 ^ 0b010 = 0b101 = 5 (7 ^ 2 = 5)


def test_issue_eight_to_two():
    """Rule 'toggle all even bits': 8 (0b1000) becomes 2."""
    assert even_bit_toggle_number(8) == 2  # 0b1000 ^ 0b1010 = 0b0010 = 2 (8 ^ 10 = 2)


def test_issue_sixteen_to_twentysix():
    """Rule 'toggle all even bits': 16 (0b10000) becomes 26."""
    assert even_bit_toggle_number(16) == 26  # 0b10000 ^ 0b01010 = 0b11010 = 26 (16 ^ 10 = 26)


def test_issue_255_to_85():
    """Rule 'toggle all even bits': 255 (0b11111111) becomes 85."""
    assert even_bit_toggle_number(255) == 85  # 0b11111111 ^ 0b10101010 = 0b01010101 = 85 (255 ^ 170 = 85)


def test_contract_returns_int():
    """Contract: function must return an int and not break callers."""
    assert isinstance(even_bit_toggle_number(10), int)


def test_contract_parity_preserved():
    """Contract from 'toggle even bits': LSB position 1 is odd so parity is preserved."""
    assert even_bit_toggle_number(9) % 2 == 1  # 9=0b1001 odd -> 3=0b0011 odd, 3 % 2 = 1
